from catalog import MODELS

class Switcher:
    def __init__(self):
        self.active = 'ordinary'
        self.pending = None
        self.serial = 0

    def select(self, model, agent):
        self.serial += 1
        self.pending = (self.serial, model)
        if model not in MODELS:
            raise ValueError('unknown')
        return self.serial

    def complete(self, ticket, success):
        if self.pending:
            if success:
                self.active = self.pending[1]
            self.pending = None

    def status(self):
        return {'active': self.active, 'pending': self.pending, 'ready': self.pending is None}

