from due import next_due

def poll(jobs, now):
    ready=[]
    for job in jobs:
        if job['due'] <= now:
            ready.append({'id':job['id'],'scheduled':job['due']})
            job['due']=next_due(job['due'],job['interval'],now)
    return ready,jobs

